//! M86.5 (docs/DESIGN.md §84.5): a column that holds liquid, its product
//! lines needing their pumps — the holdup plant (`crude_unit_holdup.toml`,
//! untouched) with a product line on every draw, built inline here as the
//! M86.4 grade plant's (a 15 m fall to a pump of 100 m head, a check valve, a
//! water cooler, 1.5 km of rundown to a tank at the draws' level) — and the
//! two plants made of it, `crude_unit_holdup_pumps_grade.toml` (that line)
//! and `crude_unit_holdup_pumps_lifted.toml` (the tanks out of the column's
//! reach), generated by `tools/steptime/prototypes/m86_5/make_holdup_pumped.py`.

use crate::product_line_reference::build;
use crate::product_pumps::{lift, on_solver};
use crate::short_draw_line::{flow, set_pump, tick};
use refinery_core::engine::Engine;
use refinery_core::graph::{HoldupState, NodeKind};
use refinery_core::snapshot::{HoldupOperation, Snapshot};
use refinery_core::traits::LevelLimit;
use refinery_core::units::KgPerSec;
use refinery_solvers::network::{march_draw_lines, LineFlash};

const HOLDUP_PLANT: &str = include_str!("../../../scenarios/crude_unit_holdup.toml");
const GRADE_PLANT: &str = include_str!("../../../scenarios/crude_unit_holdup_pumps_grade.toml");
const LIFTED_PLANT: &str = include_str!("../../../scenarios/crude_unit_holdup_pumps_lifted.toml");

/// The oil draws, top down, by their line's first pipe's prefix, and the
/// stage each draws from.
const OIL: [(&str, usize); 5] = [
    ("naphtha", 0),
    ("kerosene", 4),
    ("diesel", 7),
    ("gas_oil", 10),
    ("residue", 13),
];

/// Each product's cooling water [kg/s], cooler UA [kW/K] and rundown
/// diameter [m] (`make_pumped.py grade`).
const GRADE: [(&str, f64, f64, f64); 5] = [
    ("naphtha", 75.0, 150.0, 0.154),
    ("kerosene", 115.0, 90.0, 0.131),
    ("diesel", 190.0, 120.0, 0.14),
    ("gas_oil", 150.0, 70.0, 0.119),
    ("residue", 460.0, 100.0, 0.152),
];

/// `src` (a plant whose draws run straight to their tanks through
/// `<product>_draw`, 20 m of 15 cm) with the grade plant's product line on
/// every draw.
fn grade_lines(src: &str) -> String {
    let mut src = src.to_string();
    for (product, water, ua, diameter) in GRADE {
        let tank = format!("{product}_tank");
        let before = src.clone();
        src = src
            .replacen(
                &format!("{{ outlet = \"{tank}\","),
                &format!("{{ outlet = \"{product}_pump\","),
                1,
            )
            .replacen(
                &format!(
                    "name = \"{product}_draw\"\nfrom = \"column\"\nto = \"{tank}\"\n\
                     length_m = 20.0\ndiameter_m = 0.15"
                ),
                &format!(
                    "name = \"{product}_suction\"\nfrom = \"column\"\nto = \"{product}_pump\"\n\
                     length_m = 20.0\ndiameter_m = 0.20\nelevation_change_m = -15.0"
                ),
                1,
            );
        assert_eq!(
            src.matches(&format!("{product}_pump")).count(),
            before.matches(&format!("{product}_pump")).count() + 2,
            "the {product} draw was not rewired"
        );
        src.push_str(&format!(
            r#"
[nodes.{product}_pump]
type = "pump"
h0_m = 100.0
a = 2000.0
on = true

[nodes.{product}_check]
type = "check_valve"
kv = 400.0
full_open_bar = 0.015

[nodes.{product}_cooler]
type = "water_cooler"
ua_kw_per_k = {ua}
water_inlet_c = 30.0
water_flow_kg_per_s = {water}

[[pipes]]
name = "{product}_discharge"
from = "{product}_pump"
to = "{product}_check"
length_m = 30.0
diameter_m = 0.15

[[pipes]]
name = "{product}_check_outlet"
from = "{product}_check"
to = "{product}_cooler"
length_m = 1.0
diameter_m = 0.15

[[pipes]]
name = "{product}_rundown"
from = "{product}_cooler"
to = "{tank}"
length_m = 1500.0
diameter_m = {diameter}
elevation_change_m = 15.0
"#
        ));
    }
    src
}

fn holdup_state(engine: &Engine) -> HoldupState {
    let node = engine.graph.find_node("column").unwrap();
    match &engine.graph.node(node).kind {
        NodeKind::Column {
            cascade: Some(spec),
            ..
        } => spec
            .holdup
            .as_ref()
            .and_then(|h| h.state.clone())
            .expect("a column that holds liquid"),
        _ => panic!("the column is a cascade column"),
    }
}

/// Each component's mass the column holds [kg]: its stages' and its drum's.
fn inventory(held: &HoldupState) -> Vec<f64> {
    let mut total = vec![0.0; held.drum_composition.fractions().len()];
    let stages = held.stage_liquid.iter().zip(&held.stage_composition);
    let drum = std::iter::once((&held.drum_liquid, &held.drum_composition));
    for (mass, composition) in stages.chain(drum) {
        for (slot, w) in total.iter_mut().zip(composition.fractions()) {
            *slot += mass.value() * w;
        }
    }
    total
}

/// The column's worst per-component imbalance over one tick [kg/s]: what
/// came in, less what left (the draws and any slop), less what it now holds
/// more.
fn worst_books(engine: &Engine, before: &[f64], after: &[f64], s: &Snapshot) -> f64 {
    let dt = 0.1;
    let column = s.nodes.iter().find(|n| n.name == "column").unwrap();
    let slop = column
        .column_operation
        .as_ref()
        .map(|op| op.slop.clone())
        .unwrap_or_default();
    let carried = |name: &str, c: usize| {
        let e = s.edges.iter().find(|e| e.name == name).unwrap();
        e.stream.mass_flow.value() * e.stream.composition.fractions()[c]
    };
    let mut worst: f64 = 0.0;
    for c in 0..engine.slate.len() {
        let mut balance = carried("transfer_line", c) - (after[c] - before[c]) / dt;
        for (product, _) in OIL {
            balance -= carried(&format!("{product}_suction"), c);
        }
        for vessel in &slop {
            balance -= vessel.flow_kg_s * vessel.composition.fractions()[c];
        }
        worst = worst.max(balance.abs());
    }
    worst
}

/// The line limit the column ran `draw` (a plan index) at this tick [kg/s],
/// if its line was short.
fn ran_short(engine: &Engine, draw: usize) -> Option<(f64, f64)> {
    let column = engine.graph.find_node("column").unwrap();
    engine.node_states().column_separation[&column]
        .short_draws
        .iter()
        .find(|short| short.draw == draw)
        .map(|short| (short.wanted.value(), short.delivered.value()))
}

/// **A stopped side pump on a column that holds liquid**: the line still
/// carries part of the draw (the column pushes it through the stopped pump),
/// the column runs the draw at what the line delivers and the rest stays on
/// its tray and runs down — the plant runs on, every component's books closing. Was
/// (M86.5's probe): the run halted on the first tick, the column's draw
/// 1.3e-7 of itself over its line's limit — set in moles at the tray's
/// start-of-tick liquid, reported in mass at its end-of-tick liquid.
fn a_stopped_pump_runs_at_its_line_limit(product: &str, index: usize) {
    let src = grade_lines(HOLDUP_PLANT);
    let mut engine = build(&src).unwrap();
    let s = tick(&mut engine, 30);
    let normal = flow(&s, &format!("{product}_suction"));
    set_pump(&mut engine, product, false);
    let mut worst: f64 = 0.0;
    for t in 0..600 {
        let before = inventory(&holdup_state(&engine));
        engine
            .tick()
            .unwrap_or_else(|e| panic!("{product} tick {t}: the plant must run: {e}"));
        let s = engine.snapshot();
        let after = inventory(&holdup_state(&engine));
        worst = worst.max(worst_books(&engine, &before, &after, &s));
        let drawn = flow(&s, &format!("{product}_suction"));
        let cut = drawn / normal;
        assert!(
            cut > 0.5 && cut < 0.6,
            "{product} tick {t}: carries {cut} of its flow"
        );
        let (wanted, got) = ran_short(&engine, index).expect("the line short");
        assert!(wanted > got, "{product} tick {t}: {wanted} {got}");
        assert!(
            (drawn - got).abs() <= 1e-9 * got,
            "{product} tick {t}: drawn {drawn}, its line's limit {got}"
        );
    }
    // As at rest (`column_holdup::each_component_is_conserved_every_tick`).
    assert!(worst < 1e-8, "{product}: {worst} kg/s");
}

#[test]
fn a_stopped_kerosene_pump_on_a_holding_column_runs_at_its_line_limit() {
    a_stopped_pump_runs_at_its_line_limit("kerosene", 1);
}

/// The same for the distillate (what its line cannot take stays in the
/// drum) and the bottoms (in the base): set in moles at the drum's or the
/// base's start-of-tick liquid like a side draw, and held to the limit the
/// same way.
#[test]
fn a_stopped_naphtha_pump_on_a_holding_column_runs_at_its_line_limit() {
    a_stopped_pump_runs_at_its_line_limit("naphtha", 0);
}

#[test]
fn a_stopped_residue_pump_on_a_holding_column_runs_at_its_line_limit() {
    a_stopped_pump_runs_at_its_line_limit("residue", 4);
}

/// The most `product`'s line delivers [kg/s], its pump on or off, marched
/// from the plant's state after 150 ticks: the line's stored flow set far past
/// anything it can carry, so the march's short-line search (§84.2) finds its
/// limit.
fn most(src: &str, product: &str, on: bool) -> f64 {
    let mut engine = build(src).unwrap();
    tick(&mut engine, 150);
    if !on {
        set_pump(&mut engine, product, false);
    }
    let name = format!("{product}_suction");
    let line: Vec<_> = engine
        .graph
        .draw_lines()
        .into_iter()
        .map(|(_, _, line)| line.to_vec())
        .find(|line| engine.graph.pipe(line[0]).name == name)
        .expect("a product line");
    for &edge in &line {
        engine.graph.pipe_mut(edge).stream.mass_flow = KgPerSec(2000.0);
    }
    let pins = march_draw_lines(
        &engine.graph,
        &engine.slate,
        engine.node_states(),
        LineFlash::LIQUID,
    )
    .unwrap();
    pins.draw_delivered
        .get(&line[0])
        .expect("short at 2000 kg/s")
        .value()
}

/// **The margins the plants were measured at** (the M86.5 probe), as a
/// multiple of each product's flow: at grade a stopped pump's line still
/// carries 0.54–0.58 of it, a running one 1.9–2.0 times it; on high ground a
/// stopped pump's line carries nothing, a running one 2.1–4.0 times it.
#[test]
fn the_holding_plants_lines_need_their_pumps_by_the_margins_measured() {
    for plant in [GRADE_PLANT, LIFTED_PLANT] {
        let mut engine = build(plant).unwrap();
        let s = tick(&mut engine, 150);
        for (product, _) in OIL {
            let normal = flow(&s, &format!("{product}_suction"));
            let on = most(plant, product, true) / normal;
            let off = most(plant, product, false) / normal;
            println!("M86_5 {product}: running {on:.3}x, stopped {off:.3}x");
            if plant == GRADE_PLANT {
                assert!(on > 1.8, "grade {product}: running {on}");
                assert!(off > 0.53 && off < 0.59, "grade {product}: stopped {off}");
            } else {
                assert!(on > 2.0, "lifted {product}: running {on}");
                assert_eq!(off, 0.0, "lifted {product}: runs without its pump");
            }
        }
    }
}

fn holdup(s: &Snapshot) -> HoldupOperation {
    let column = s.nodes.iter().find(|n| n.name == "column").unwrap();
    column
        .column_operation
        .as_ref()
        .and_then(|op| op.holdup)
        .expect("a column that holds liquid")
}

/// Each pump stopped in turn for five minutes, then started: nothing halts;
/// the stopped product runs at what its line delivers — at grade 0.53–0.60 of
/// its flow through an open disc, on high ground nothing, its disc shut — no
/// pipe of its line running back, every component's books closing every
/// tick; what the line cannot take stays in the column, so by five minutes
/// the drum (naphtha) or the base (residue) has risen, or a side product's
/// rest has raised both the naphtha and the residue (the plant files'
/// headers, measured on the newton solver; the game solver's the same to
/// within these bands). Started again, a side draw is back at its flow, the
/// naphtha and the residue above theirs, emptying what the column held.
fn stopped_pumps_on_the_holding_column(plant: &str, solver: &str, lifted: bool) {
    let src = on_solver(plant, solver);
    for (index, (product, _)) in OIL.iter().enumerate() {
        let mut engine = build(&src).unwrap();
        let s = tick(&mut engine, 30);
        let normal: Vec<f64> = OIL
            .iter()
            .map(|(p, _)| flow(&s, &format!("{p}_suction")))
            .collect();
        let at_rest = holdup(&s);
        let rest = s.clone();
        set_pump(&mut engine, product, false);
        let mut worst: f64 = 0.0;
        let mut s = s;
        for t in 0..3000 {
            let before = inventory(&holdup_state(&engine));
            engine
                .tick()
                .unwrap_or_else(|e| panic!("{solver} {product} tick {t}: the plant must run: {e}"));
            s = engine.snapshot();
            let after = inventory(&holdup_state(&engine));
            worst = worst.max(worst_books(&engine, &before, &after, &s));
            let cut = flow(&s, &format!("{product}_suction")) / normal[index];
            for pipe in ["suction", "discharge", "check_outlet", "rundown"] {
                let carried = flow(&s, &format!("{product}_{pipe}"));
                assert!(
                    carried >= 0.0,
                    "{solver} {product} tick {t}: the {pipe} runs back: {carried}"
                );
            }
            if lifted {
                assert!(cut < 1e-9, "{solver} {product} tick {t}: still runs: {cut}");
                if t > 0 {
                    assert_eq!(lift(&s, product), 0.0, "{solver} {product} tick {t}");
                }
            } else {
                assert!(
                    cut > 0.53 && cut < 0.60,
                    "{solver} {product} tick {t}: carries {cut} of its flow"
                );
                assert!(lift(&s, product) > 0.0, "{solver} {product} tick {t}: shut");
            }
        }
        assert!(worst < 1e-8, "{solver} {product}: {worst} kg/s");
        let now: Vec<f64> = OIL
            .iter()
            .zip(&normal)
            .map(|((p, _), n)| flow(&s, &format!("{p}_suction")) / n)
            .collect();
        let held = holdup(&s);
        println!(
            "M86_5 {solver} {product} 5 min: {now:?}, drum {:.3}, base {:.3}",
            held.drum_level, held.base_level
        );
        match *product {
            "naphtha" => {
                let risen = if lifted { 0.58 } else { 0.53 };
                assert!(held.drum_level > risen, "{solver}: {held:?}");
                assert!(now[4] > 1.03, "{solver}: {now:?}");
            }
            "residue" => {
                let risen = if lifted { 0.61 } else { 0.55 };
                assert!(held.base_level > risen, "{solver}: {held:?}");
                assert!(
                    (held.drum_level - at_rest.drum_level).abs() < 0.01,
                    "{solver}: {held:?}"
                );
            }
            _ => {
                assert!(now[0] > 1.01, "{solver} {product}: {now:?}");
                assert!(now[4] > 1.03, "{solver} {product}: {now:?}");
            }
        }
        set_pump(&mut engine, product, true);
        let s = tick(&mut engine, 300);
        let back = flow(&s, &format!("{product}_suction")) / normal[index];
        if *product == "naphtha" || *product == "residue" {
            assert!(back > 1.0, "{solver} {product}: not emptying: {back}");
        } else {
            // Released: its line no longer short, and the draw back at its
            // share of the oil fed — of the feed the column was handed at the
            // tick's start, which the transfer line has moved from by a few
            // 1e-7 of itself by the tick's end.
            assert_eq!(ran_short(&engine, index), None, "{solver} {product}");
            let share =
                |s: &Snapshot| flow(s, &format!("{product}_suction")) / flow(s, "transfer_line");
            assert!(
                (share(&s) / share(&rest) - 1.0).abs() < 1e-5,
                "{solver} {product}: not released: {back}"
            );
        }
    }
}

#[test]
fn slow_stopped_pumps_on_the_holding_grade_plant() {
    stopped_pumps_on_the_holding_column(GRADE_PLANT, "newton", false);
}

#[test]
fn slow_stopped_pumps_on_the_holding_grade_plant_on_the_game_solver() {
    stopped_pumps_on_the_holding_column(GRADE_PLANT, "simple", false);
}

#[test]
fn slow_stopped_pumps_on_the_holding_lifted_plant() {
    stopped_pumps_on_the_holding_column(LIFTED_PLANT, "newton", true);
}

#[test]
fn slow_stopped_pumps_on_the_holding_lifted_plant_on_the_game_solver() {
    stopped_pumps_on_the_holding_column(LIFTED_PLANT, "simple", true);
}

/// On high ground a stopped residue pump fills the base in about 20
/// minutes (the plant file's header); then the whole bottoms goes to slop,
/// off-spec, its alarm the base's `"full"`, and the plant runs on.
#[test]
fn slow_a_stopped_residue_pump_on_high_ground_fills_the_base_to_slop() {
    let mut engine = build(LIFTED_PLANT).unwrap();
    let s = tick(&mut engine, 30);
    let bottoms = flow(&s, "residue_suction");
    set_pump(&mut engine, "residue", false);
    let s = tick(&mut engine, 11_400);
    let held = holdup(&s);
    assert!(held.base_level < 1.0, "full before 19 min: {held:?}");
    let s = tick(&mut engine, 1_200);
    let held = holdup(&s);
    assert_eq!(held.base_limit, LevelLimit::Full, "{held:?}");
    let column = s.nodes.iter().find(|n| n.name == "column").unwrap();
    let slop: f64 = column
        .column_operation
        .as_ref()
        .unwrap()
        .slop
        .iter()
        .map(|vessel| vessel.flow_kg_s)
        .sum();
    assert!(
        slop > 0.9 * bottoms,
        "slop {slop} of a bottoms of {bottoms}"
    );
    assert!(flow(&s, "residue_suction") < 1e-9);
}

/// At grade a stopped residue pump's line still carries about half the
/// bottoms, so the base fills more slowly — and then runs past full with its
/// line still short: the bottoms at what its line delivers, the excess to
/// slop on top (`ColumnStep::scale_to_limits`' slop, the only plant that
/// reaches it). Seventy minutes: nothing halts, the base full, its slop
/// flowing, the residue at its line's limit, every component's books closing.
fn grade_residue_runs_to_slop(solver: &str) {
    let mut engine = build(&on_solver(GRADE_PLANT, solver)).unwrap();
    let s = tick(&mut engine, 30);
    let bottoms = flow(&s, "residue_suction");
    set_pump(&mut engine, "residue", false);
    let mut worst: f64 = 0.0;
    let mut full_at = None;
    for t in 0..42_000 {
        let before = inventory(&holdup_state(&engine));
        engine
            .tick()
            .unwrap_or_else(|e| panic!("{solver} tick {t}: the plant must run: {e}"));
        let s = engine.snapshot();
        let after = inventory(&holdup_state(&engine));
        worst = worst.max(worst_books(&engine, &before, &after, &s));
        if full_at.is_none() && holdup(&s).base_limit == LevelLimit::Full {
            full_at = Some(t);
        }
        if t % 6000 == 5999 {
            println!(
                "M86_5 {solver} grade residue {} min: {:.3} of its flow, base {:.3}",
                (t + 1) / 600,
                flow(&s, "residue_suction") / bottoms,
                holdup(&s).base_level
            );
        }
    }
    let s = engine.snapshot();
    let held = holdup(&s);
    let column = s.nodes.iter().find(|n| n.name == "column").unwrap();
    let slop: f64 = column
        .column_operation
        .as_ref()
        .unwrap()
        .slop
        .iter()
        .map(|vessel| vessel.flow_kg_s)
        .sum();
    let drawn = flow(&s, "residue_suction");
    let (_, limit) = ran_short(&engine, 4).expect("the residue line short");
    println!("M86_5 {solver} grade residue: full at tick {full_at:?}, slop {slop:.2} kg/s, residue {drawn:.3} kg/s, books {worst:e}");
    assert_eq!(held.base_limit, LevelLimit::Full, "{solver}: {held:?}");
    assert!(slop > 0.3 * bottoms, "{solver}: slop {slop}");
    assert!(
        (drawn - limit).abs() <= 1e-9 * limit,
        "{solver}: {drawn} {limit}"
    );
    assert!(drawn > 0.4 * bottoms, "{solver}: {drawn}");
    assert!(worst < 1e-8, "{solver}: {worst} kg/s");
}

#[test]
fn slow_a_stopped_residue_pump_at_grade_fills_the_base_to_slop() {
    grade_residue_runs_to_slop("newton");
}

#[test]
fn slow_a_stopped_residue_pump_at_grade_fills_the_base_to_slop_on_the_game_solver() {
    grade_residue_runs_to_slop("simple");
}
